// CSD_RATIONALE_BEGIN
// Root cause of 4.1% accuracy (attempt 33): The inner constrained loop called
// CloseSpanIfComplete, which closes the span immediately on the FIRST complete
// arithmetic prefix. A single identifier like "n1" is already a valid expression,
// so the span closed after one token producing tiny spans (avg 2.23 tokens, median 1).
// The correct expressions (e.g., "n1 + n1*mult + n2 + n3") were visible in the
// model's chain-of-thought but the span only captured the first token.
//
// Fix: Replace CloseSpanIfComplete inner loops with CloseSpanWithinBudget, which
// tracks the LONGEST complete prefix during generation and closes at that point.
// This forces the model to generate the full arithmetic expression before closing.
//
// The 2 unterminated spans from attempt 33 resulted from a tiny budget remaining
// when << was detected late; the new strategy caps free-text at 80% of budget and
// caps constrained at 150 tokens, guaranteeing a meaningful constrained window.
//
// Strategy phases:
//   Phase 1:  Chunk-based free generation (80% budget) stopping at <<.
//   Phase 1b: Single-step fallback with RenderedEndsWith for edge cases.
//   Phase 2:  CloseSpanWithinBudget(min(150, remaining)) on open span.
//   Phase 3:  If no span emitted, OpenConstrainedSpan + CloseSpanWithinBudget.
//   Phase 4:  Safety close with all remaining budget.
//
// Guidance: no << >> examples in text, clear variable-name and int() rules.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedChunk): insideConstrainedOut remains false until
//     stoppedOnOpenSpan fires; EnterObservedConstrainedSpan then sets
//     currentConstrainedOut := [] which satisfies IsValidPrefix([]) by
//     method precondition. Invariant holds vacuously while false. ✓
//
//   Phase 1b (UnconstrainedStep + RenderedEndsWith): identical argument;
//     EnterObservedConstrainedSpan sets currentConstrainedOut := []. ✓
//
//   Phases 2/3b/4 (CloseSpanWithinBudget): library postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut) on both the closed and
//     still-open return paths. ✓
//
//   Phase 3a (OpenConstrainedSpan): sets currentConstrainedOut := [],
//     satisfying IsValidPrefix([]). ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: UnconstrainedChunk postcondition gives
//     |generatedOut| <= |generated_old| + stepsUsed; we add stepsUsed to steps.
//     chunkLim is capped so steps + su <= freeBudget <= maxSteps. ✓
//   Phase 1b: UnconstrainedStep appends at most 1 token; steps increments by 1. ✓
//   Phases 2/3b/4: CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated_old| + budget; we add budget to steps;
//     budget <= maxSteps - steps_old so steps_new <= maxSteps. ✓
//   Phase 3a: OpenConstrainedSpan appends "<<" (1 token); steps incremented by 1
//     under guard steps < maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the end write: The answer is EXPR where EXPR is the arithmetic expression. Rules: (1) Use EXACTLY the variable names from the problem without curly braces, e.g. if the problem has {n1} write n1, if {price} write price. (2) Use int() when multiplying an integer by a fraction: int(n * frac). (3) Only use: variable names, numbers, +, -, *, /, (, ), int(). (4) No LaTeX, no dollar signs, no backslashes, no curly braces in the expression.");

var steps: nat := 0;

var freeBudget: nat := (maxSteps * 80) / 100;
if freeBudget > maxSteps { freeBudget := maxSteps; }
if freeBudget == 0 && maxSteps > 0 { freeBudget := 1; }

var hasCompletedSpan: bool := false;

// Phase 1: Chunk-based free generation watching for <<
while steps < freeBudget && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant freeBudget <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget - steps
