  var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, cBud);
  generated := wg;
  insideConstrainedOut := wi;
  currentConstrainedOut := wc;
  steps := steps + cBud;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 3: Force-open span if no complete span emitted yet
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
