  var cBud2: nat := 150;
  if cBud2 > remB2 { cBud2 := remB2; }
  var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, cBud2);
  generated := wg2;
  insideConstrainedOut := wi2;
  currentConstrainedOut := wc2;
  steps := steps + cBud2;
